import type { Metadata, Viewport } from 'next';
// Self-hosted variable fonts (public/fonts, generated by scripts/fonts/sync-fonts.mjs). Same family
// names as before, so every font-family string keeps working. Same origin, immutable cache, no
// render-blocking request to Google. One file per family and subset covers all weights, and
// unicode-range means a page only downloads the subsets (arabic / latin) its text uses.
import './fonts.css';
import './globals.css';
import { SITE_URL } from '@/lib/seo';

export const metadata: Metadata = {
  metadataBase: new URL(SITE_URL),
  title: 'MAGHAREBIT | مغاربيت',
  description: 'تطبيق المغاربة في الخارج',
  manifest: '/manifest.json',
  applicationName: 'MAGHAREBIT POS',
  icons: {
    icon: [{ url: '/favicon.ico', sizes: 'any' }, { url: '/icon.svg', type: 'image/svg+xml' }],
    apple: [{ url: '/apple-touch-icon.png', sizes: '180x180' }],
  },
  appleWebApp: { capable: true, title: 'MAGHAREBIT', statusBarStyle: 'black-translucent' },
  twitter: { card: 'summary_large_image' },
  // Morocco targeting hints (regional meta tags; Google relies mainly on hreflang and content).
  other: { 'mobile-web-app-capable': 'yes', 'geo.region': 'MA', 'geo.placename': 'Maroc' },
};

export const viewport: Viewport = { themeColor: '#0A2318' };

/**
 * Root layout: a pass-through. <html> and <body> are rendered per locale in app/[locale]/layout.tsx so
 * the served HTML carries the right lang and dir (a French page is lang="fr" dir="ltr" before any
 * script runs). Keep this file free of <html>: not-found.tsx and global-error.tsx render their own.
 */
export default function RootLayout({ children }: { children: React.ReactNode }) {
  return children;
}
